569	      "description": "`ok` is false when the action was not carried out.",
570	      "content": {
571	       "application/json": {
572	        "schema": {
573	         "type": "object",
574	         "properties": {
575	          "ok": {
576	           "type": "boolean"
577	          },
578	          "error": {
579	           "type": "string"
580	          }
581	         }
582	        }
583	       }
584	      }
585	     },
586	     "500": {
