import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1"
OUT = sys.argv[1]

HELP = r'''
import datetime, re, json
HOL = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def nth_bd_after(d, n):
    c = 0
    x = d
    while c < n:
        x = x + datetime.timedelta(days=1)
        if isbd(x):
            c += 1
    return x
def spoken(d):
    return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y')
def get_now(v):
    s = str(v.get('now') or '').strip()
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        try:
            return datetime.datetime.fromisoformat(s[:10] + 'T00:00')
        except Exception:
            return datetime.datetime(2026, 10, 14, 11, 0)
def is_true(x):
    return x is True or str(x).strip().lower() == 'true'
'''

POST_PREFIX = r'''
try:
    V = vars
except NameError:
    V = dict()
'''


def hook(body):
    return HELP + POST_PREFIX + "try:\n" + "\n".join("    " + l for l in body.strip("\n").split("\n")) + "\nexcept Exception:\n    pass\n"


def api_tool(name, desc, body_props, required, pre="", post="", retries=0, mapping=None):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(body_props)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "default": f"{BASE}/{name}"},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                    "body": {"type": "object", "properties": props, "required": required},
                },
            },
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


def cond_or(*cs):
    return {"logic": "or", "conditions": list(cs)}


def eq(v, o):
    return {"variable": v, "operator": "equals", "operand": o}


CLOSED = {"target_node": "hang_up", "description": "The call was closed",
          "condition": cond_or(eq("close_call_response.data.ok", "true"), eq("close_call_response.data.ok", "True"))}

