"""Generate out/w2-A.workflow.json for Brief A."""
import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1"
OUT = sys.argv[1]

HELP = r'''
import datetime, re, json
HOL = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def nth_bd_after(d, n):
    c = 0
    x = d
    while c < n:
        x = x + datetime.timedelta(days=1)
        if isbd(x):
            c += 1
    return x
def spoken(d):
    return d.strftime('%A') + ' ' + str(d.day) + ' ' + d.strftime('%B %Y')
def get_now(v):
    s = str(v.get('now') or '').strip()
    try:
        return datetime.datetime.fromisoformat(s[:16])
    except Exception:
        try:
            return datetime.datetime.fromisoformat(s[:10] + 'T00:00')
        except Exception:
            return datetime.datetime(2026, 10, 14, 11, 0)
def is_true(x):
    return x is True or str(x).strip().lower() == 'true'
'''

POST_PREFIX = r'''
try:
    V = vars
except NameError:
    V = dict()
'''


def hook(body):
    return HELP + POST_PREFIX + "try:\n" + "\n".join("    " + l for l in body.strip("\n").split("\n")) + "\nexcept Exception:\n    pass\n"


def api_tool(name, desc, body_props, required, pre="", post="", retries=0, mapping=None):
    props = {"customer_id": {"type": "string", "default": "{{customer_id}}"}}
    props.update(body_props)
    t = {
        "type": "function",
        "config": {"timeoutMs": 12000, "maxRetries": retries},
        "function": {
            "name": name,
            "handler": "__function__:api_call",
            "description": desc,
            "parameters": {
                "type": "object",
                "properties": {
                    "url": {"type": "string", "default": f"{BASE}/{name}"},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}}},
                    "body": {"type": "object", "properties": props, "required": required},
                },
            },
        },
    }
    if pre:
        t["pre_process_code"] = pre
    if post:
        t["post_process_code"] = post
    if mapping:
        t["response_mapping"] = mapping
    return t


def cond_or(*cs):
    return {"logic": "or", "conditions": list(cs)}


def eq(v, o):
    return {"variable": v, "operator": "equals", "operand": o}


CLOSED = {"target_node": "hang_up", "description": "The call was closed",
          "condition": cond_or(eq("close_call_response.data.ok", "true"), eq("close_call_response.data.ok", "True"))}

# ---------------------------------------------------------------- close_call
CLOSE_PRE = hook(r'''
V['close_block'] = ''
b = config.get('body')
if isinstance(b, dict):
    o = str(b.get('outcome') or '').strip()
    r = str(b.get('reason') or '').strip()
    if r.startswith('{') or r.lower() in ('', 'none', 'null'):
        r = ''
    rec = str(V.get('promise_recorded') or '') == 'yes'
    tr = str(V.get('transfer_reason') or '')
    if o == 'transferred' and tr:
        r = tr
    elif rec and o != 'transferred':
        o = 'promise'
        r = ''
    allowed = dict()
    allowed['promise'] = []
    allowed['paid'] = []
    allowed['transferred'] = ['restructuring', 'human', 'support']
    allowed['no_promise'] = ['refused', 'hardship', 'dispute', 'service_error']
    allowed['not_verified'] = ['failed', 'declined']
    allowed['not_reached'] = ['callback', 'no_callback', 'wrong_number', 'deceased', 'unclear']
    if o not in allowed:
        V['close_block'] = 'Not closed: outcome must be one of ' + ', '.join(sorted(allowed)) + '. Call close_call again with a valid outcome.'
        b.pop('outcome', None)
    elif allowed[o] and r not in allowed[o]:
        V['close_block'] = 'Not closed: outcome ' + o + ' needs a reason, one of: ' + ', '.join(allowed[o]) + '. Call close_call again with the right reason.'
        b.pop('outcome', None)
    else:
        b['outcome'] = o
        if allowed[o]:
            b['reason'] = r
        else:
            b.pop('reason', None)
''')

CLOSE_POST = hook(r'''
if isinstance(result, dict):
    result.pop('header', None)
    d = result.get('data')
    if not isinstance(d, dict):
        d = dict()
        result['data'] = d
    blk = str(V.get('close_block') or '')
    if is_true(d.get('ok')):
        d['what_to_do_next'] = 'The call is closed. Say nothing more and call no tool.'
    elif blk:
        d['what_to_do_next'] = blk
    else:
        d['what_to_do_next'] = 'close_call failed. Call close_call once more with the same outcome and reason.'
''')

CLOSE_DESC = ("End the call record. CALL it exactly once, as the very last tool call, in the same message as your goodbye "
              "(thank the customer and say goodbye first). Outcomes and reasons: "
              "promise (no reason) = a promise was recorded; paid (no reason) = customer says they already paid this amount; "
              "transferred + restructuring / human / support = after transfer_to_agent succeeded; "
              "no_promise + refused / hardship / dispute / service_error; "
              "not_verified + failed / declined; "
              "not_reached + callback / no_callback / wrong_number / deceased / unclear.")


def close_tool():
    return api_tool("close_call", CLOSE_DESC, {
        "outcome": {"type": "string", "enum": ["promise", "paid", "transferred", "no_promise", "not_verified", "not_reached"],
                    "default": "{{close_outcome}}",
                    "description": "One of: promise, paid, transferred, no_promise, not_verified, not_reached."},
        "reason": {"type": "string",
                   "enum": ["refused", "hardship", "dispute", "service_error", "restructuring", "human", "support",
                            "failed", "declined", "callback", "no_callback", "wrong_number", "deceased", "unclear", "none"],
                   "default": "{{close_reason}}",
                   "description": "transferred: restructuring|human|support. no_promise: refused|hardship|dispute|service_error. "
                                  "not_verified: failed|declined. not_reached: callback|no_callback|wrong_number|deceased|unclear. "
                                  "Use none for promise and paid."},
    }, ["customer_id", "outcome"], pre=CLOSE_PRE, post=CLOSE_POST)


# ---------------------------------------------------------------- transfer
TR_PRE = hook(r'''
V['transfer_block'] = ''
b = config.get('body')
if isinstance(b, dict):
    q = str(b.get('queue') or '').strip()
    m = dict()
    m['restructuring'] = 'restructuring'
    m['general'] = 'human'
    m['support'] = 'support'
    if q in m:
        V['transfer_queue'] = q
        V['pending_transfer_reason'] = m[q]
        V['transfer_reason'] = m[q]
    else:
        V['transfer_block'] = 'Not transferred: queue must be restructuring, general or support.'
        b.pop('queue', None)
''')

TR_POST = hook(r'''
if isinstance(result, dict):
    result.pop('header', None)
    d = result.get('data')
    if not isinstance(d, dict):
        d = dict()
        result['data'] = d
    reason = str(V.get('pending_transfer_reason') or '')
    if is_true(d.get('ok')):
        d['what_to_do_next'] = ('The transfer is arranged. Tell the customer you are transferring them now, thank them, say goodbye, '
                                'and call close_call with outcome transferred and reason ' + (reason or 'matching the queue (restructuring->restructuring, general->human, support->support)') + '.')
    else:
        V['transfer_reason'] = ''
        blk = str(V.get('transfer_block') or '')
        d['what_to_do_next'] = (blk + ' ' if blk else '') + ('The transfer did NOT work. Do not say they are being transferred. '
                                'Call transfer_to_agent once more. If it fails again, tell the customer you could not transfer them, '
                                'thank them, say goodbye and call close_call: support -> no_promise hardship; '
                                'restructuring or general -> no_promise refused.')
''')


def transfer_tool(queues, desc):
    return api_tool("transfer_to_agent", desc, {
        "queue": {"type": "string", "enum": queues, "default": "{{transfer_queue_choice}}",
                  "description": "Queue. One of: " + ", ".join(queues) + "."},
    }, ["customer_id", "queue"], pre=TR_PRE, post=TR_POST)


# ---------------------------------------------------------------- callback
CB_PRE = hook(r'''
V['cb_block'] = ''
b = config.get('body')
if isinstance(b, dict):
    now = get_now(V)
    today = now.date()
    nbd = nth_bd_after(today, 1)
    ds = str(b.get('date') or '').strip()[:10]
    ts = str(b.get('time') or '').strip()
    mt = re.match(r'^(\d{1,2})[:.h]?(\d{2})?', ts)
    why = ''
    try:
        dd = datetime.date.fromisoformat(ds)
    except Exception:
        dd = None
        why = 'the date is not a valid YYYY-MM-DD date'
    if not why and not mt:
        why = 'the time is not HH:MM'
    if not why:
        hh = int(mt.group(1))
        mm = int(mt.group(2) or 0)
        b['time'] = '%02d:%02d' % (hh, mm)
        b['date'] = dd.isoformat()
        when = datetime.datetime(dd.year, dd.month, dd.day, hh, mm)
        if dd != today and dd != nbd:
            why = 'the day must be today (' + spoken(today) + ') or the next business day (' + spoken(nbd) + ')'
        elif (hh, mm) < (10, 0) or (hh, mm) > (19, 0):
            why = 'the time must be between 10:00 and 19:00'
        elif when <= now:
            why = 'the time must be later than now (' + now.strftime('%H:%M') + ' today)'
    if why:
        V['cb_block'] = 'NOT booked because ' + why + '.'
        b.pop('date', None)
''')

CB_POST = hook(r'''
if isinstance(result, dict):
    result.pop('header', None)
    d = result.get('data')
    if not isinstance(d, dict):
        d = dict()
        result['data'] = d
    blk = str(V.get('cb_block') or '')
    if is_true(d.get('ok')):
        d['what_to_do_next'] = ('The callback is booked. Tell the person the bank will call back then, thank them, say goodbye, '
                                'and call close_call with outcome not_reached and reason callback.')
    elif blk:
        d['what_to_do_next'] = (blk + ' If this was the first time outside the window, ask once for another day and time inside the window. '
