PREPARE_CODE = HELP + r'''
def find_products(v):
    for k in ('products', 'get_account_response.data.products', 'get_account.data.products'):
        x = v.get(k)
        if isinstance(x, str):
            try:
                x = json.loads(x)
            except Exception:
                x = None
        if isinstance(x, list) and x:
            return x
    rows = dict()
    for k in list(v.keys()):
        m = re.search(r'products\.(\d+)\.(\w+)$', str(k))
        if m:
            rows.setdefault(int(m.group(1)), dict())[m.group(2)] = v.get(k)
    return [rows[i] for i in sorted(rows)]
def money(x):
    return '%.2f' % float(x)
try:
    now = get_now(vars)
    today = now.date()
    prods = [p for p in find_products(vars) if isinstance(p, dict)]
    late = [p for p in prods if float(p.get('past_due') or 0) > 0] or prods
    p = late[0]
    t = str(p.get('type') or '')
    if t == 'credit_card':
        words = 'credit card ending ' + str(p.get('card_last4') or '')
        floor = float(p.get('minimum_payment'))
    elif t == 'car_loan':
        words = 'car loan'
        floor = float(p.get('instalment_amount'))
    else:
        words = 'personal loan'
        floor = float(p.get('instalment_amount'))
    full = float(p.get('past_due'))
    if floor > full:
        floor = full
    dl = int(float(p.get('days_late')))
    band = 'early' if dl <= 7 else 'late'
    deadline = nth_bd_after(today, 12 if band == 'early' else 7)
    # last business day of this week
    def last_bd_of_week(d):
        sun = d + datetime.timedelta(days=6 - d.weekday())
        x = sun
        while not isbd(x):
            x = x - datetime.timedelta(days=1)
        return x
    a1 = last_bd_of_week(today)
    if a1 <= today:
        a1 = last_bd_of_week(today + datetime.timedelta(days=7 - today.weekday()))
    if a1 > deadline:
        a1 = deadline
    valid = []
    x = today
    while x <= deadline:
        if isbd(x):
            valid.append(x.isoformat())
        x = x + datetime.timedelta(days=1)
    cal = []
    x = today
    end = deadline + datetime.timedelta(days=10)
    while x <= end:
        tag = 'today, ' if x == today else ''
        if x > deadline:
            st = 'AFTER the deadline: do not record; say the latest date you can record is ' + spoken(deadline) + ' and offer it'
        elif isbd(x):
            st = 'OK to record'
        else:
            nb = x
            while not isbd(nb):
                nb = nb + datetime.timedelta(days=1)
            what = 'weekend' if x.weekday() >= 5 else 'bank holiday'
            if nb > deadline:
                st = what + ', not a business day: offer ' + spoken(deadline)
            else:
                st = what + ', not a business day: offer ' + spoken(nb) + ' (' + nb.isoformat() + ')'
        cal.append('- ' + tag + spoken(x) + ' = ' + x.isoformat() + ': ' + st)
        x = x + datetime.timedelta(days=1)
    mon = today - datetime.timedelta(days=today.weekday())
    names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    wk = []
    for i in range(7):
        a = mon + datetime.timedelta(days=i)
        n = a + datetime.timedelta(days=7)
        wk.append('- "this ' + names[i] + '" = ' + a.isoformat() + ('' if a >= today else ' (already past)') + '; "next ' + names[i] + '" = ' + n.isoformat())
    vars['acct_state'] = 'ok'
    vars['product_id'] = str(p.get('product_id') or '')
    vars['product_words'] = words
    vars['past_due_num'] = round(full, 2)
    vars['past_due_str'] = money(full)
    vars['floor_num'] = round(floor, 2)
    vars['floor_str'] = money(floor)
    vars['days_late_str'] = str(dl)
    vars['band'] = band
    vars['deadline_iso'] = deadline.isoformat()
    vars['deadline_spoken'] = spoken(deadline)
    vars['attempt1_spoken'] = spoken(a1)
    vars['attempt1_iso'] = a1.isoformat()
    vars['valid_dates'] = ','.join(valid)
    vars['calendar_table'] = '\n'.join(cal)
    vars['weekday_table'] = '\n'.join(wk)
    if band == 'early':
        vars['attempts_plan'] = ('Early band: you have ONE persuasion attempt.\n'
            '- Attempt 1: propose paying ' + money(full) + ' (or ' + money(floor) + ' if the customer already said the full amount is too much) on ' + spoken(a1) + '.\n'
            '- There is no attempt 2. After attempt 1 is refused, stop.')
    else:
        vars['attempts_plan'] = ('Late band: you have TWO persuasion attempts.\n'
            '- Attempt 1: propose paying ' + money(full) + ' (or ' + money(floor) + ' if the customer already said the full amount is too much) on ' + spoken(a1) + '.\n'
            '- Attempt 2: propose paying ' + money(floor) + ' on ' + spoken(deadline) + ' (the deadline). Say that the rest stays overdue.\n'
            '- After attempt 2 is refused, stop.')
except Exception as e:
    vars['acct_state'] = 'error'
    vars['product_id'] = ''
    vars['product_words'] = 'account'
    vars['past_due_str'] = ''
    vars['floor_str'] = ''
    vars['days_late_str'] = ''
    vars['band'] = ''
    vars['deadline_spoken'] = ''
    vars['attempt1_spoken'] = ''
    vars['valid_dates'] = ''
    vars['calendar_table'] = ''
    vars['weekday_table'] = ''
    vars['attempts_plan'] = ''
    vars['prepare_error'] = str(e)[:200]
'''


def code_node(name, code, nxt, extra_transitions=()):
    return {
        "name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": nxt,
        "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                         "parameters": {"type": "object", "properties": {
                             "code": {"type": "string", "default": code},
                             "timeout_ms": {"type": "number", "default": 10000}}}}}],
        "transitions": list(extra_transitions) + [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}],
    }


